css:
.cta {
  border: none;
  background: none;
  cursor: pointer;
  transition: all 0.3s ease;
  padding-bottom: 7px;
  padding-left: 2px;
  letter-spacing: 4px;
  font-size: 14px;
  text-transform: uppercase;
  margin-right: 10px;
  position: relative;
}

.cta::before {
  content: "\21DD";
  font-size: 28px;
  position: absolute;
  top: -12px;
  right: -10px;
  transform: translateX(100%);
}

.cta:active {
  transform: scale(0.9);
}

.cta {
  position: relative;
  color: black;
  padding-bottom: 10px;
}

.cta::after {
  content: "";
  position: absolute;
  width: 100%;
  transform: scaleX(0);
  height: 2px;
  bottom: 0;
  left: 0;
  background-color: #000000;
  transform-origin: bottom right;
  transition: transform 0.25s ease-out;
}

.cta:hover::after {
  transform: scaleX(1);
  transform-origin: bottom left;
}
